import{_ as t,o as i,c as n,aa as o}from"./chunks/framework.BAs_AphD.js";const a="/buildary-help-preview/media/en/tickets/uvodni_tickets.png",u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction","wiki":"en:tickets:start"},"headers":[],"relativePath":"en/tickets/index.md","filePath":"en/tickets/index.md","lastUpdated":1794388980000}'),r={name:"en/tickets/index.md"};function s(l,e,c,d,h,p){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><figure class="shot" style="--w:600px;"><img src="'+a+'" alt="List of projects" width="580" loading="lazy"></figure><p>The <strong>Ticket Management</strong> module of the Buildary application is designed for systematic task management on projects. Tickets are shared online among members of the construction project team, giving them access to all important information. Workers are notified of their tickets immediately after they are entered into the application and can start working on them. Likewise, the ticket author is continuously informed of any changes made to the ticket by the person responsible for resolving it.</p><p>Thanks to the Buildary application being hosted in the cloud, information is available anytime and anywhere an Internet connection is available. The mobile application also allows users to work in offline mode.</p><p>We recommend launching the <strong>web application</strong> from the <strong><a href="https://buildary.online" target="_blank" rel="noreferrer">www.buildary.online</a></strong> website, where current information related to the application is also published, along with notifications about webinars, training sessions, and other important events.</p><p>The Ticket Management module is also available in the <strong>mobile application</strong>, which is ideal for entering data directly on the construction site. The application is freely available for Android and iOS operating systems. For more information, see <strong>Mobile application - <a href="/buildary-help-preview/en/tickets/m_firststeps">Getting Started with the Mobile Application</a></strong>.</p><h2 id="compatibility-with-other-modules" tabindex="-1">Compatibility with other modules <a class="header-anchor" href="#compatibility-with-other-modules" aria-label="Permalink to &quot;Compatibility with other modules&quot;">​</a></h2><p>The Buildary.online application has three modules:</p><ul><li>Construction Diary</li><li>Ticket Management</li><li>Records of Completed Work</li></ul><p>Although each module can be used independently, their interconnection can be used to advantage, making users&#39; work even easier.</p><p>The Task Management module is linked to the Construction Diary module, allowing new tasks to be created directly from entries in the diary.</p>',11)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
